installer-gui-script.script:

function fatal(title, message) {
  my.result.type = 'Fatal';
  my.result.title = title;
  my.result.message = message;
  return false;
}
function klaraCheck() {
  if (system.sysctl('hw.optional.arm64') != 1) {
    return fatal('Klara Wisper צריכה מק עם שבב Apple',
      'במחשב הזה יש מעבד Intel. Klara Wisper עובדת רק על מק עם שבב Apple (M1 ומעלה).\n\n' +
      'This Mac has an Intel processor. Klara Wisper needs a Mac with Apple silicon (M1 or later).');
  }
  if (system.compareVersions(system.version.ProductVersion, '14.4') < 0) {
    return fatal('צריך לעדכן את macOS',
      'Klara Wisper צריכה macOS 14.4 ומעלה. מעדכנים ב: הגדרות המערכת > כללי > עדכון תוכנה, ופותחים את ההתקנה שוב.\n\n' +
      'Klara Wisper needs macOS 14.4 or later: System Settings > General > Software Update, then open the installer again.');
  }
  var mem = system.sysctl('hw.memsize');
  if (mem && mem < 6 * 1024 * 1024 * 1024) {
    return fatal('אין מספיק זיכרון',
      'Klara Wisper צריכה לפחות 8GB זיכרון.\n\nKlara Wisper needs at least 8 GB of memory.');
  }
  return true;
}
